def _create_chunk(
    chunk_id: str,
    source_id: str,
    document_id: str,
    content: str,
    company_id: str,
    topic: str,
    created_at_iso: str = "2024-06-01T12:00:00Z",
) -> DocumentChunk:
    """Helper to construct a deterministic frozen DocumentChunk."""
    meta = ChunkMetadata(
        source_id=source_id,
        document_id=document_id,
        version_id="v1",
        company_id=company_id,
        workspace_id="ws_trap_eval",
        source_url=f"https://benchmark.ci.internal/docs/{company_id}/{document_id}",
        source_category=topic,
        collected_at=datetime(2024, 6, 1, 12, 0, 0, tzinfo=timezone.utc),
        start_char=0,
        end_char=len(content),
        chunk_index=0,
        total_chunks=1,
    )
    return DocumentChunk(
        chunk_id=chunk_id,
        document_id=document_id,
        version_id="v1",
        content=content,
        content_hash=compute_content_hash(content),
        metadata=meta,
        created_at=datetime(2024, 6, 1, 12, 0, 0, tzinfo=timezone.utc),
    )


